import{_ as l,a0 as i,w as s,s as p,ao as r,I as n,x as t,a1 as d,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Linux 用户的 3 個命令列小技巧 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 用户的 3 個命令列小技巧 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 用户的 3 個命令列小技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 用户的 3 個命令列小技巧 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150527 3 Useful Hacks Every Linux User Must Know","title":"Linux 用户的 3 個命令列小技巧","tag":"201506","desc":""},"relativePath":"201506/20150527 3 Useful Hacks Every Linux User Must Know.md","filePath":"[post].md"}'),c={name:"201506/20150527 3 Useful Hacks Every Linux User Must Know.md"};function u(x,e,m,f,w,h){const o=i("Link");return s(),p("div",null,[e[15]||(e[15]=r(`<h1 id="linux-用户的-3-個命令列小技巧" tabindex="-1">Linux 用户的 3 個命令列小技巧 <a class="header-anchor" href="#linux-用户的-3-個命令列小技巧" aria-label="Permalink to “Linux 用户的 3 個命令列小技巧”">​</a></h1><p>Linux世界充滿了樂趣，我們越深入進去，就會發現越多有趣的事物。我們會努力給你提供一些小技巧，讓你和其他人有所不同，下面就是我們準備的3個小技巧。</p><h3 id="_1-如何在不使用cron的情況調度linux下的任務" tabindex="-1">1. 如何在不使用Cron的情況調度Linux下的任務 <a class="header-anchor" href="#_1-如何在不使用cron的情況調度linux下的任務" aria-label="Permalink to “1. 如何在不使用Cron的情況調度Linux下的任務”">​</a></h3><p>在Linux下，調度一個任務/命令稱之為Cron。當我們需要調度一個任務時，我們會使用Cron，但你知道我們在不使用Cron的情況也可以調度一個在將來時間運行的任務嗎？你可以按照如下建議操作……</p><p>每5秒鐘運行一個命令（date）然後將結果寫入到一個文件（data.txt）。為了實現這一點，我們可以直接在命令提示符運行如下單行腳本。</p><pre><code>$ while true; do date &gt;&gt; date.txt ; sleep 5 ; done &amp;
</code></pre><p>上述腳本的解釋：</p><ul><li><code>while true</code> ：讓腳本進入一個條件總為真的循環中，也就是製造一個死循環，將裏邊的命令一遍遍地重複運行。</li><li><code>do</code> ：<code>do</code>是<code>while</code>語句中的關鍵字，它之後的命令會被執行，在它後邊可以放置一個或一系列命令。</li><li><code>date &gt;&gt; date.txt</code> ：運行date命令，並將其輸出寫入到data.txt文件中。注意我們使用<code>&gt;&gt;</code>，而不是<code>&gt;</code>。</li><li><code>&gt;&gt;</code> ：對文件（date.txt）進行追加寫的操作，這樣每次運行命令後，輸出內容會被追加到文件中。如果使用<code>&gt;</code>的話，則會一遍遍地覆蓋之前的內容。</li><li><code>sleep 5</code> ：讓腳本處於5秒睡眠狀態，然後再運行之後的命令。注意這裏的時間單位只能用秒。也就是説如果你想讓命令每6分鐘運行一次，你應該使用<code>sleep 360</code>。</li><li><code>done</code> ：<code>while</code>循環語句塊結束的標記。</li><li><code>&amp;</code> ：將整個進程放到後台運行。</li></ul><p>類似地，我們可以這樣運行任何腳本。下邊的例子是每100秒運行一個名為<code>script_name.sh</code>的腳本。</p><p>另外值得一提的是上面提到的腳本文件必須處於當前目錄中，否則需要使用完整路徑（<code>/home/$USER/…/script_name.sh</code>）。實現如上功能的單行腳本如下：</p><pre><code>$ while true; do /bin/sh script_name.sh ; sleep 100 ; done &amp;
</code></pre><p><strong>總結</strong>：上述的單行腳本並不是Cron的替代品，因為Cron工具支持眾多選項，更加靈活，可定製性也更高。然而如果我們想運行某些測試，比如I/O評測，上述的單行腳本也管用。</p>`,12)),n("p",null,[e[1]||(e[1]=t("還可以參考：",-1)),d(o,{href:"http://www.tecmint.com/11-cron-scheduling-task-examples-in-linux/"},{default:a(()=>[...e[0]||(e[0]=[t("Linux 下 11 個定時調度任務例子",-1)])]),_:1})]),e[16]||(e[16]=r(`<h3 id="_2-如何不使用clear命令清空終端的內容" tabindex="-1">2. 如何不使用clear命令清空終端的內容 <a class="header-anchor" href="#_2-如何不使用clear命令清空終端的內容" aria-label="Permalink to “2. 如何不使用clear命令清空終端的內容”">​</a></h3><p>你如何清空終端的內容？你可能會認為這是一個傻問題。好吧，大家都清楚可以使用<code>clear</code>命令。如果養成使用<code>ctrl + l</code>快捷鍵的習慣，我們會節省大量時間。</p><p><code>Ctrl + l</code>快捷鍵的效果和<code>clear</code>命令一樣。所以下一次你就可以使用<code>ctrl + l</code>來清空終端的內容了。</p><p><strong>總結</strong>：因為<code>ctrl + l</code>是一個快捷鍵，我們不可以在腳本中使用。所以如果我們需要在腳本中清空屏幕內容，還是需要使用<code>clear</code>命令。但我能想到的所有其他情況，<code>ctrl + l</code>都更加有效。</p><h3 id="_3-在其它目錄運行一個命令-然後自動返回當前工作目錄" tabindex="-1">3. 在其它目錄運行一個命令，然後自動返回當前工作目錄 <a class="header-anchor" href="#_3-在其它目錄運行一個命令-然後自動返回當前工作目錄" aria-label="Permalink to “3. 在其它目錄運行一個命令，然後自動返回當前工作目錄”">​</a></h3><p>這是一個很多人可能不知道的令人吃驚的技巧。你可能想在其它目錄運行任何一個命令，然後再回到當前目錄。要實現這樣的目的，你只需要將命令放在一個圓括號裏。</p><p>我們來看一個例子：</p><pre><code>avi@deb:~$ (cd /home/avi/Downloads/)
</code></pre><p>示例輸出：</p><pre><code> avi@deb:~
</code></pre><p>它首先會cd到Downloads目錄，然後又回到了之前的家目錄。也許你認為裏邊的命令根本沒有執行，或者是出了某種錯誤，因為從命令提示符看不出任何變化。讓我們簡單修改一下這個命令：</p><pre><code>avi@deb:~$ (cd /home/avi/Downloads/ &amp;&amp; ls -l)
</code></pre><p>示例輸出：</p><pre><code>-rw-r-----  1 avi  avi     54272 May  3 18:37 text1.txt
-rw-r-----  1 avi  avi     54272 May  3 18:37 text2.txt
-rw-r-----  1 avi  avi     54272 May  3 18:37 text3.txt
avi@deb:~$
</code></pre><p>在上述命令中，它首先進入Downloads目錄，然後列出文件內容，最後又回到了當前目錄。並且它證明了命令成功執行了。你可以在括號中包含任何命令，執行完都會順利返回到當前目錄。</p><p>這就是全部內容了，如果你知道任何類似的Linux技巧，你可以在文章下面的評論框中分享給我們，不要忘記將本文和朋友分享 😃</p><hr>`,17)),n("p",null,[e[3]||(e[3]=t("via: ",-1)),d(o,{href:"http://www.tecmint.com/useful-linux-hacks-commands/"},{default:a(()=>[...e[2]||(e[2]=[t("http://www.tecmint.com/useful-linux-hacks-commands/",-1)])]),_:1})]),n("p",null,[e[7]||(e[7]=t("作者：",-1)),d(o,{href:"http://www.tecmint.com/author/avishek/"},{default:a(()=>[...e[4]||(e[4]=[t("Avishek Kumar",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),d(o,{href:"https://github.com/goreliu"},{default:a(()=>[...e[5]||(e[5]=[t("goreliu",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),d(o,{href:"https://github.com/wxy"},{default:a(()=>[...e[6]||(e[6]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=t("本文由 ",-1)),d(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創翻譯，",-1)),d(o,{href:"https://linux.cn/"},{default:a(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const C=l(c,[["render",u]]);export{L as __pageData,C as default};
